"""Camera-only UI; every saved sample contains a full still and its metadata."""
HTML = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>掌纹 · 高清采集</title><style>
:root{--ink:#172d31;--muted:#687b7d;--line:#dce5e3;--green:#17654b;--paper:#f4f7f5}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px system-ui,-apple-system,sans-serif}header,main{max-width:1240px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;align-items:center;gap:16px}h1{margin:4px 0;font-size:27px;letter-spacing:-.5px}.eyebrow{font-size:12px;letter-spacing:2px;color:var(--green);font-weight:700}.sub{color:var(--muted);font-size:14px;line-height:1.6;margin:5px 0}.badge{font-size:13px;background:#e3ede7;padding:9px 13px;border-radius:30px;white-space:nowrap}.badge.error{background:#fbe7e2;color:#9e352a}main{padding-top:0}.top{display:grid;grid-template-columns:minmax(0,1.9fr) minmax(290px,1fr);gap:20px}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px}h2{font-size:17px;margin:0 0 14px}.cardhead{display:flex;align-items:center;justify-content:space-between;gap:12px}.live{position:relative;border-radius:12px;overflow:hidden;aspect-ratio:4/3;background:#15201f}.live img{width:100%;height:100%;object-fit:contain;display:block}.guide{position:absolute;inset:8%;border:1px dashed #ffffff66;border-radius:20px;pointer-events:none}.live-caption{position:absolute;left:14px;bottom:14px;background:#122a25b8;color:#fff;padding:7px 10px;border-radius:8px;font-size:12px;pointer-events:none}.help{color:var(--muted);font-size:13px;line-height:1.65}.counter{font:700 20px system-ui}.progress{height:5px;background:#e6ece8;border-radius:8px;overflow:hidden;margin:14px 0}.progress span{display:block;width:0;height:100%;background:var(--green);transition:width .25s}.action{width:100%;border:0;border-radius:12px;background:var(--green);color:#fff;font:650 18px system-ui;padding:17px;cursor:pointer}.action:disabled{opacity:.5;cursor:wait}.keyboard{font-size:12px;font-weight:400;opacity:.75;margin-left:12px}kbd{font:inherit;border:1px solid currentColor;border-radius:4px;padding:2px 5px}label{display:block;font-size:14px;font-weight:600;margin:15px 0 7px}input,select,textarea{font:inherit;width:100%;padding:11px 12px;border:1px solid #ccd7d2;border-radius:9px;background:#fff;color:var(--ink)}input:focus,select:focus,textarea:focus{outline:2px solid #aed5c3;outline-offset:1px}textarea{resize:vertical;min-height:65px}.hands{display:flex;gap:10px}.hands label{margin:0;flex:1}.hands input{position:absolute;opacity:0;width:1px;height:1px}.hands span{display:block;text-align:center;padding:12px;border:1px solid var(--line);border-radius:9px;cursor:pointer}.hands input:checked+span{border-color:var(--green);background:#e9f3ec;color:var(--green)}.hands input:disabled+span{cursor:default;opacity:.75}details{margin-top:20px;border-top:1px solid var(--line);padding-top:16px}summary{cursor:pointer;color:var(--muted);font-size:14px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.secondary{font:inherit;border:1px solid var(--line);background:#fff;border-radius:9px;padding:10px 13px;cursor:pointer;color:var(--ink)}.secondary:disabled{opacity:.5}.actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:14px}.download{display:inline-block;color:var(--green);text-decoration:none;font-weight:650;font-size:14px;padding:10px 12px;background:#e9f3ec;border-radius:9px}.status{margin-top:14px;min-height:45px;padding:12px;border-radius:9px;background:#f1f5f2;font-size:14px;line-height:1.6;overflow-wrap:anywhere}.status.error{background:#fff0e9;color:#9a3a25}.section{margin-top:20px}.thumbs{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:8px}.thumb{padding:0;background:#edf1ed;border:2px solid transparent;border-radius:8px;cursor:pointer;overflow:hidden;color:var(--ink)}.thumb img{width:100%;aspect-ratio:4/3;object-fit:cover;display:block}.thumb span{display:block;font:600 12px system-ui;padding:5px}.thumb.selected{border-color:var(--green)}.inspect{display:grid;grid-template-columns:minmax(0,2fr) minmax(220px,1fr);gap:18px;margin-top:18px}.full{width:100%;max-height:520px;object-fit:contain;background:#eef2ed;border-radius:10px;cursor:crosshair}canvas{display:block;width:100%;aspect-ratio:1;background:#eff3ee;border-radius:10px;image-rendering:pixelated}.links{display:flex;gap:14px;flex-wrap:wrap;margin:10px 0}.links a{color:var(--green);font-size:13px}.saved{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 0;border-top:1px solid var(--line)}.saved strong{font-size:14px}.saved small{display:block;font-size:12px;color:var(--muted);line-height:1.7}.empty{color:var(--muted);font-size:14px;padding:10px 0}[hidden]{display:none!important}@media(max-width:850px){header,main{padding:16px}.top{grid-template-columns:1fr}.thumbs{grid-template-columns:repeat(5,minmax(0,1fr))}.inspect{grid-template-columns:1fr}.card{padding:18px}.zoom{max-width:360px}.keyboard{display:none}}@media(max-width:460px){header{align-items:flex-start}h1{font-size:23px}.badge{font-size:11px;padding:8px}.saved{align-items:flex-start}.saved small{max-width:190px}}
.danger{color:#a63c30;border-color:#e8c9c2}.danger:hover:not(:disabled){background:#fff0eb}
</style></head><body>
<header><div><div class="eyebrow">PALM CAPTURE</div><h1>掌纹高清采集</h1><p class="sub">先保留完整原图，随后离线提取 ROI 与评测。</p></div><span id="camera" class="badge">正在连接相机…</span></header>
<main><div class="top"><section class="card"><div class="cardhead"><h2>实时取景</h2><span id="counter" class="counter">0 / 10</span></div><div class="live"><img id="live" src="/frame.jpg" alt="相机实时画面"><div class="guide"></div><div class="live-caption">掌缘、手指根部和指缝完整入镜 · 避免贴近镜头</div></div><p class="help">虚线仅作取景参考。手指自然张开，检查指缝和掌纹是否清楚；保持距离与灯光一致。</p><div class="progress"><span id="bar"></span></div><button id="capture" class="action" disabled>连接相机后拍摄</button><div class="actions"><button id="finish" class="secondary" hidden>结束本组</button><button id="switch" class="secondary">换另一只手</button><a id="download" class="download" hidden>下载本组 ZIP</a></div><div id="status" class="status" role="status" aria-live="polite">填写受试编号、选择左右手，即可拍摄。</div></section>
<section class="card"><h2>本组标签</h2><p class="sub">同一组使用同一只手，每组最多 10 张。</p><label for="subject">受试编号</label><input id="subject" maxlength="40" placeholder="例如 p01" autocomplete="off" pattern="[A-Za-z0-9_-]+"><label>哪只手</label><div class="hands"><label><input type="radio" name="hand" value="left"><span>左手</span></label><label><input type="radio" name="hand" value="right"><span>右手</span></label></div><details><summary>采集条件（可选）</summary><div class="row"><div><label for="background">背景</label><select id="background"><option value="existing">现有背景</option><option value="white">白纸</option><option value="other">其他</option></select></div><div><label for="distance">距离 / cm</label><input id="distance" type="number" min="5" max="100" step="0.5" placeholder="例如 30"></div></div><label for="notes">灯光与备注</label><textarea id="notes" maxlength="200" placeholder="例如 IR 灯常亮、固定支架"></textarea></details><p class="help">保存完整分辨率照片、左右手标签、拍摄时间及曝光／增益参数。拍摄时不做自动裁剪或识别。</p></section></div>
<section class="card section"><div class="cardhead"><h2>本组照片</h2><button id="delete-photo" class="secondary danger" disabled>删除选中照片</button></div><p class="help">点击缩略图选择照片。删除后可继续补拍；移除的原图保留在树莓派回收目录。</p><div id="thumbs" class="thumbs"></div><p id="empty" class="empty">本组尚无照片。</p><div id="inspect" class="inspect" hidden><div><img id="full" class="full" alt="完整高清原图"><div class="links"><a id="full-link" target="_blank">打开原图</a><a id="metadata-link" target="_blank">拍摄参数</a></div><p id="photo-info" class="help"></p></div><div class="zoom"><canvas id="zoom" width="512" height="512"></canvas><p class="help">点击左侧照片，检查该位置的原始像素。放大检查不会生成或保存 ROI。</p></div></div></section>
<section class="card section"><h2>已保存的采集组</h2><div id="sessions" class="empty">正在读取…</div></section></main>
<script>
const $=id=>document.getElementById(id),camera=$('camera'),capture=$('capture'),status=$('status'),full=$('full');
let batch={phase:'idle',sample_ids:[],captured:0},ready=false,busy=false,signature='',selected=null,seenSession=null,previewUrl=null;
const formInputs=[$('subject'),$('background'),$('distance'),$('notes'),...document.querySelectorAll('input[name=hand]')];
const handValue=()=>document.querySelector('input[name=hand]:checked')?.value||'';
function say(text,error=false){status.textContent=text;status.className='status'+(error?' error':'')}
function labels(){const subject=$('subject').value.trim(),hand=handValue();if(!/^[A-Za-z0-9_-]{1,40}$/.test(subject))throw Error('请填写受试编号，只使用英文字母、数字、_ 或 -。');if(!hand)throw Error('请选择左手或右手。');return{subject,hand,background:$('background').value,distance_cm:$('distance').value,notes:$('notes').value,client_time:new Date().toISOString()}}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.message||'请求失败');return d}
function controls(){const active=batch.phase==='await_hand';for(const el of formInputs)el.disabled=busy||active;capture.disabled=busy||!ready;capture.textContent=busy?'正在处理…':active?`拍第 ${batch.captured+1} 张 · 高清原图`:batch.phase==='complete'?'开始新组 · 拍第 1 张':'拍第 1 张 · 开始本组';if(!busy){const hint=document.createElement('span');hint.className='keyboard';hint.innerHTML='<kbd>空格</kbd> 拍照';capture.append(hint)}$('counter').textContent=`${batch.captured||0} / 10`;$('bar').style.width=(batch.captured||0)*10+'%';$('finish').hidden=!active;$('finish').disabled=busy;$('switch').disabled=busy;$('download').hidden=!batch.session_id||!batch.captured;if(batch.session_id)$('download').href='/api/collection/session/'+encodeURIComponent(batch.session_id)+'.zip';deleteControls()}
function deleteControls(){const index=(batch.sample_ids||[]).indexOf(selected);$('delete-photo').disabled=busy||index<0;$('delete-photo').textContent=index<0?'删除选中照片':`删除第 ${index+1} 张`;for(const b of document.querySelectorAll('[data-delete-session]'))b.disabled=busy}
async function showPhoto(id){selected=id;deleteControls();for(const b of $('thumbs').children)b.classList.toggle('selected',b.dataset.id===id);try{const m=await api('/api/collection/sample/'+encodeURIComponent(id)+'/metadata.json');if(selected!==id)return;const base='/api/collection/sample/'+encodeURIComponent(id);full.src=base+'/full.jpg';$('full-link').href=base+'/full.jpg';$('metadata-link').href=base+'/metadata.json';$('inspect').hidden=false;$('photo-info').textContent=`${m.subject} · ${m.hand==='left'?'左手':'右手'} · ${m.width}×${m.height}`+(m.exposure_ms==null?'':` · 曝光 ${Number(m.exposure_ms).toFixed(1)} ms`)+(m.analogue_gain==null?'':` · 增益 ${Number(m.analogue_gain).toFixed(2)}`)}catch(e){if(selected===id)say(e.message,true)}}
function thumbnails(){const ids=batch.sample_ids||[],key=ids.join(',');if(key===signature)return;signature=key;$('thumbs').replaceChildren();$('empty').hidden=ids.length>0;for(const [i,id]of ids.entries()){const b=document.createElement('button');b.className='thumb';b.dataset.id=id;b.title='查看第 '+(i+1)+' 张';const img=document.createElement('img');img.src='/api/collection/sample/'+encodeURIComponent(id)+'/thumbnail.jpg';img.alt='第 '+(i+1)+' 张高清照片';const label=document.createElement('span');label.textContent=String(i+1).padStart(2,'0');b.append(img,label);b.onclick=()=>showPhoto(id);$('thumbs').append(b)}if(ids.length)showPhoto(ids.at(-1));else{selected=null;$('inspect').hidden=true;full.removeAttribute('src');$('zoom').getContext('2d').clearRect(0,0,512,512)}deleteControls()}
async function refresh(){const d=await api('/api/status');ready=Boolean(d.camera_ready)&&!d.error;camera.textContent=d.error?'相机异常':ready?`${(d.capture_size||[3280,2464]).join(' × ')} · 已连接`:'正在连接相机…';camera.className='badge'+(d.error?' error':'');batch=d.highres_batch||{phase:'idle',captured:0,sample_ids:[]};if(batch.session_id&&seenSession!==batch.session_id){seenSession=batch.session_id;$('subject').value=batch.subject||'';for(const h of document.querySelectorAll('input[name=hand]'))h.checked=h.value===batch.hand;$('background').value=batch.background||'existing';$('distance').value=batch.distance_cm??'';$('notes').value=batch.notes||''}thumbnails();controls()}
async function poll(){if(!busy)try{await refresh()}catch(e){ready=false;camera.textContent='连接中断';camera.className='badge error';controls()}setTimeout(poll,800)}
async function preview(){try{const r=await fetch('/frame.jpg?t='+Date.now(),{cache:'no-store'});if(r.ok){const next=URL.createObjectURL(await r.blob()),old=previewUrl;previewUrl=next;$('live').src=next;if(old)URL.revokeObjectURL(old)}}catch(e){}setTimeout(preview,250)}
capture.onclick=async()=>{if(busy||!ready)return;busy=true;controls();try{if(batch.phase!=='await_hand'){const l=labels();batch=await api('/api/collection/start-batch',l);try{localStorage.setItem('palm_capture_labels',JSON.stringify(l))}catch(e){}}say('正在保存高清原图，请保持手的位置…');const d=await api('/api/collection/capture-batch',{client_time:new Date().toISOString()});say(d.phase==='complete'?'10 张已保存。可以下载整组，或切换手别开始下一组。':`第 ${d.sample_index} 张已保存。可以继续拍摄，也可以移开后重新放置手掌。`);await refreshSessions()}catch(e){say('拍摄未完成：'+e.message,true)}finally{busy=false;await refresh().catch(()=>{});controls()}};
async function finish(){if(batch.phase==='await_hand')await api('/api/collection/abandon-batch',{});seenSession=null;signature='__reset__';await refresh();await refreshSessions()}
$('finish').onclick=async()=>{if(busy)return;busy=true;controls();try{const count=batch.captured;await finish();say(`本组已结束，${count} 张原图已保留。可在下方下载。`)}catch(e){say(e.message,true)}finally{busy=false;controls()}};
$('switch').onclick=async()=>{if(busy)return;const next=handValue()==='left'?'right':'left';busy=true;controls();try{await finish();for(const h of document.querySelectorAll('input[name=hand]'))h.checked=h.value===next;say(`已切换到${next==='left'?'左手':'右手'}。下一次拍摄会开始新组。`)}catch(e){say(e.message,true)}finally{busy=false;controls()}};
document.addEventListener('keydown',e=>{if(e.code!=='Space'||e.repeat||['INPUT','TEXTAREA','SELECT','BUTTON'].includes(e.target.tagName))return;e.preventDefault();if(!capture.disabled)capture.click()});
function zoomAt(x,y){if(!full.naturalWidth)return;const size=Math.min(512,full.naturalWidth,full.naturalHeight),sx=Math.max(0,Math.min(full.naturalWidth-size,x-size/2)),sy=Math.max(0,Math.min(full.naturalHeight-size,y-size/2));const ctx=$('zoom').getContext('2d');ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,512,512);ctx.drawImage(full,sx,sy,size,size,0,0,512,512)}
full.onload=()=>zoomAt(full.naturalWidth/2,full.naturalHeight/2);full.onclick=e=>{const box=full.getBoundingClientRect(),scale=Math.min(box.width/full.naturalWidth,box.height/full.naturalHeight),w=full.naturalWidth*scale,h=full.naturalHeight*scale,x=e.clientX-box.left-(box.width-w)/2,y=e.clientY-box.top-(box.height-h)/2;if(x>=0&&y>=0&&x<=w&&y<=h)zoomAt(x/scale,y/scale)};
async function deleteSelected(){if(busy||!selected)return;const id=selected,session=batch.session_id,ids=batch.sample_ids,index=ids.indexOf(id),next=ids[index+1]||ids[index-1];if(index<0||!confirm(`删除本组第 ${index+1} 张照片？\n删除后可补拍，原图会移入树莓派回收目录。`))return;busy=true;controls();deleteControls();selected=null;try{await api('/api/collection/delete-sample',{session_id:session,sample_id:id});await refresh();if(next&&(batch.sample_ids||[]).includes(next))await showPhoto(next);await refreshSessions();say(`已删除第 ${index+1} 张，本组剩余 ${batch.captured} 张，可以继续补拍。`)}catch(e){say('删除未完成：'+e.message,true)}finally{busy=false;await refresh().catch(()=>{});controls();deleteControls()}}
async function deleteSession(s){if(busy||!confirm(`删除 ${s.subject} · ${s.hand==='left'?'左手':'右手'} 的整组 ${s.sample_count} 张照片？\n原图和组信息会移入树莓派回收目录。`))return;busy=true;controls();deleteControls();try{await api('/api/collection/delete-session',{session_id:s.session_id});await refresh();await refreshSessions();say(`已删除该组 ${s.sample_count} 张照片，原图已移入回收目录。`)}catch(e){say('删除未完成：'+e.message,true)}finally{busy=false;await refresh().catch(()=>{});controls();deleteControls()}}
$('delete-photo').onclick=deleteSelected;
async function refreshSessions(){try{const d=await api('/api/collection/sessions');$('sessions').replaceChildren();const sessions=(d.sessions||[]).filter(s=>s.sample_count>0);if(!sessions.length){$('sessions').textContent='暂无已保存的采集组。';return}for(const s of sessions){const row=document.createElement('div');row.className='saved';const info=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small');title.textContent=`${s.subject} · ${s.hand==='left'?'左手':'右手'} · ${s.sample_count} 张`;meta.textContent=s.session_id;info.append(title,meta);const actions=document.createElement('div');actions.className='actions';const link=document.createElement('a');link.className='download';link.href='/api/collection/session/'+encodeURIComponent(s.session_id)+'.zip';link.textContent='下载 ZIP';const remove=document.createElement('button');remove.className='secondary danger';remove.dataset.deleteSession=s.session_id;remove.textContent='删除整组';remove.disabled=busy;remove.onclick=()=>deleteSession(s);actions.append(link,remove);row.append(info,actions);$('sessions').append(row)}}catch(e){$('sessions').textContent='暂时无法读取已保存的采集组。'}}
try{const l=JSON.parse(localStorage.getItem('palm_capture_labels')||'null');if(l){$('subject').value=l.subject||'';$('background').value=l.background||'existing';$('distance').value=l.distance_cm||'';$('notes').value=l.notes||'';for(const h of document.querySelectorAll('input[name=hand]'))h.checked=h.value===l.hand}}catch(e){}
preview();poll();refreshSessions();setInterval(()=>{if(!busy)refreshSessions()},10000);
</script></body></html>'''
